// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    PRIVATE_ETH_CELL c;
    function setUp() public { c = new PRIVATE_ETH_CELL(); }
    function testFuzz_property(uint256 initVal, uint256 newVal) public {
        initVal = bound(initVal, 0, type(uint128).max);
        newVal = bound(newVal, 0, type(uint128).max);
        vm.assume(initVal != newVal);

        address actor = address(0xA11CE);
        vm.prank(actor);
        c.SetMinSum(initVal);
        vm.prank(actor);
        c.Initialized();

        // After initialization, SetMinSum must not change MinSum.
        vm.prank(actor);
        try c.SetMinSum(newVal) { /* P reverts here; M succeeds */ } catch { }

        assertTrue(c.MinSum() == initVal);
    }
}
